def pieces(shape_rc):  # shape as set of cells
    cells = sorted(shape_rc)
    R = max(r for r,c in cells)+1; C = max(c for r,c in cells)+1
    s = set(cells)
    pieces = []
    for r,c in cells:
        # 2x2 square
        sq = [(r,c),(r,c+1),(r+1,c),(r+1,c+1)]
        if all(p in s for p in sq): pieces.append(('sq',tuple(sq)))
        # L trominoes: 2x2 minus one corner
        for miss in [(r,c+1),(r+1,c),(r+1,c+1),(r,c)]:
            L = [p for p in sq if p!=miss]
            if all(p in s for p in L): pieces.append(('L',miss,tuple(L)))
    return pieces

